package io.aetheris.orchestrator.trading;
import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Service public class ManualMarketDataAdapter implements MarketDataAdapter {private final Map<String,MarketDataSnapshot> data=new ConcurrentHashMap<>();public String id(){return "manual-stage8";}public boolean available(){return true;}public MarketDataSnapshot ingest(MarketDataSnapshot s){if(s==null||s.symbol()==null||s.symbol().isBlank()||s.bars().isEmpty())throw new IllegalArgumentException("symbol and bars are required");for(MarketBar b:s.bars())if(b.close()<=0||b.high()<b.low())throw new IllegalArgumentException("Invalid market bar");MarketDataSnapshot normalized=new MarketDataSnapshot(s.symbol().trim().toUpperCase(Locale.ROOT),s.source()==null||s.source().isBlank()?id():s.source().trim(),s.observedAt()==null?Instant.now():s.observedAt(),s.bars());data.put(normalized.symbol(),normalized);return normalized;}public MarketDataSnapshot latest(String symbol,Duration maxAge){String key=symbol.trim().toUpperCase(Locale.ROOT);MarketDataSnapshot s=data.get(key);if(s==null)throw new IllegalStateException("No market data for "+key);Duration age=Duration.between(s.observedAt(),Instant.now());if(age.isNegative())age=Duration.ZERO;if(age.compareTo(maxAge)>0)throw new IllegalStateException("Market data is stale for "+key+": age="+age.toSeconds()+"s");return s;}}
